package com.amplayer.portable;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.webkit.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
public class LayoutInstrumentation extends Instrumentation {
 private Bundle arguments;private WebView web;
 @Override public void onCreate(Bundle args){arguments=args;super.onCreate(args);start();}
 private WebView find(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){WebView found=find(g.getChildAt(i));if(found!=null)return found;}}return null;}
 private String js(String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> value=new AtomicReference<>();runOnMainSync(()->web.evaluateJavascript(code,result->{value.set(result);latch.countDown();}));if(!latch.await(15,TimeUnit.SECONDS))throw new Exception("timeout");return value.get();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  JSONObject settings=Store.load(getTargetContext());settings.put("autoUpdate",false);Store.save(getTargetContext(),settings.toString());Activity activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(()->web=find(activity.getWindow().getDecorView()));runOnMainSync(()->web.getSettings().setTextZoom(Integer.parseInt(arguments.getString("zoom","100"))));Thread.sleep(1200);for(int attempt=0;attempt<50;attempt++){if("true".equals(js("typeof state!=='undefined'&&!!state")))break;Thread.sleep(400);}
  String theme=arguments.getString("theme","cyan"),language=arguments.getString("language","zh-Hant"),page=arguments.getString("page","radio");
  String check=js("(()=>{try{state.theme="+JSONObject.quote(theme)+";state.language="+JSONObject.quote(language)+";state.lastPlayed=state.stations[0]||null;observed={};applyAppearance();applyLanguage();showPage("+JSONObject.quote(page)+");persist(true);const footer=document.querySelector('.status-footer').getBoundingClientRect(),workspace=document.querySelector('.workspace').getBoundingClientRect(),list=$('library-list').getBoundingClientRect();const value={width:innerWidth,height:innerHeight,bodyWidth:document.body.scrollWidth,footerBottom:footer.bottom,footerTop:footer.top,workspaceHeight:workspace.height,listHeight:list.height,columns:getComputedStyle(document.querySelector('.workspace')).gridTemplateColumns,theme:state.theme,locale};if(value.bodyWidth>innerWidth+1||value.footerBottom>innerHeight+1||value.footerTop<0||value.workspaceHeight<40)return {error:'layout overflow',...value};return value;}catch(e){return {error:String(e),stack:e.stack};}})()");
  if(arguments.getString("update", "false").equals("true")){long before=CatalogUpdater.status(getTargetContext()).optLong("lastSuccess");js("$('btn-update').click();true");boolean done=false;for(int n=0;n<100;n++){Thread.sleep(1000);if("false".equals(js("requestInFlight"))&&CatalogUpdater.status(getTargetContext()).optLong("lastSuccess")>before){done=true;break;}}if(!done)throw new Exception("One-click download did not finish");String merged=js("(()=>{const keys=state.stations.map(x=>S.canonical(x.url));if(new Set(keys).size!==keys.length)throw Error('duplicates');if(state.remoteRevision!==api.catalog().revision)throw Error('cache not merged');return {count:keys.length,revision:state.remoteRevision};})()");if(merged.equals("null"))throw new Exception("One-click merge failed");result.putString("oneClickUpdate",merged);}
  result.putString("layout",check);if(check==null||check.equals("null")||check.contains("\"error\""))throw new Exception(check);result.putString("result","PASS");finish(Activity.RESULT_OK,result);
 }catch(Exception e){result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}}
}
